update(dt) {
    if (this.state !== 'playing') return;
    let ix = 0, iy = 0;
    const k = this.keys;
    if (k.has('arrowleft') || k.has('a')) ix -= 1;
    if (k.has('arrowright') || k.has('d')) ix += 1;
    if (k.has('arrowup') || k.has('w')) iy -= 1;
    if (k.has('arrowdown') || k.has('s')) iy += 1;
    if (ix || iy) {
        const len = Math.hypot(ix, iy);
        const step = SPEED * dt;
        // small sub-steps so the ball can never tunnel through a wall
        const n = Math.ceil(step / 5);
        for (let i = 0; i < n; i++) {
            this.x += ix / len * step / n;
            this.y += iy / len * step / n;
            this.collide();
        }
    }
    if (this.touches(DEATH)) {
        this.state = 'dead';
        msg.textContent = 'You went all the way left... you died. Press R to retry.';
    } else if (this.touches(FINISH)) {
        this.state = 'won';
        msg.textContent = 'You finished! Press R to play again.';
    }
},

