reset() {
    this.x = 500; this.y = 930; // spawn at the bottom
    this.state = 'playing';
    msg.textContent = '';
    this.applyMask();
},

setDifficulty(d) {
    this.difficulty = d;
    buttons.forEach(b => b.classList.toggle('active', b.dataset.diff === d));
    this.reset();
},

applyMask() {
    const r = MASK_RADIUS[this.difficulty];
    if (r === null) {
        canvas.style.clipPath = canvas.style.webkitClipPath = 'none';
        return;
    }
    const k = canvas.clientWidth / SIZE;
    const v = `circle(${r * k}px at ${this.x * k}px ${this.y * k}px)`;
    canvas.style.webkitClipPath = v;
    canvas.style.clipPath = v;
},

collide() {
    for (const [rx, ry, rw, rh] of WALLS) {
        const cx = Math.max(rx, Math.min(this.x, rx + rw));
        const cy = Math.max(ry, Math.min(this.y, ry + rh));
        let dx = this.x - cx, dy = this.y - cy;
        const d2 = dx * dx + dy * dy;
        if (d2 >= BALL_R * BALL_R) continue;
        if (d2 === 0) { // centre inside the rectangle: push out the shortest way
            const l = this.x - rx, r = rx + rw - this.x, t = this.y - ry, b = ry + rh - this.y;
            const m = Math.min(l, r, t, b);
            if (m === l) this.x = rx - BALL_R;
            else if (m === r) this.x = rx + rw + BALL_R;
            else if (m === t) this.y = ry - BALL_R;
            else this.y = ry + rh + BALL_R;
        } else {
            const d = Math.sqrt(d2);
            this.x = cx + dx / d * BALL_R;
            this.y = cy + dy / d * BALL_R;
        }
    }
},

touches([rx, ry, rw, rh]) {
    const cx = Math.max(rx, Math.min(this.x, rx + rw));
    const cy = Math.max(ry, Math.min(this.y, ry + rh));
    return (this.x - cx) ** 2 + (this.y - cy) ** 2 < BALL_R * BALL_R;
},

draw() {
    ctx.fillStyle = '#f4efe0';
    ctx.fillRect(0, 0, SIZE, SIZE);

    ctx.fillStyle = 'rgba(200,0,0,.8)';
    ctx.fillRect(...DEATH);

    // finish: ball-shaped rectangle
    const [fx, fy, fw, fh] = FINISH;
    ctx.fillStyle = 'gold';
    ctx.beginPath();
    ctx.roundRect(fx, fy, fw, fh, 25);
    ctx.fill();
    ctx.strokeStyle = 'darkgoldenrod';
    ctx.lineWidth = 3;
    ctx.stroke();

    ctx.fillStyle = 'saddlebrown';
    for (const w of WALLS) ctx.fillRect(...w);

    ctx.fillStyle = 'orange';
    ctx.beginPath();
    ctx.arc(this.x, this.y, BALL_R, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'black';
    ctx.lineWidth = 2;
    ctx.stroke();
},

frame(t) {
    const dt = Math.min(0.05, (t - (this.last || t)) / 1000);
    this.last = t;
    if (canvas.offsetParent !== null) {
        this.update(dt);
        this.draw();
        this.applyMask();
    }
    requestAnimationFrame(tt => this.frame(tt));
}

